package com.tnr.cityguide.config;
import com.tnr.cityguide.favorite.*;import com.tnr.cityguide.place.*;import com.tnr.cityguide.review.*;import com.tnr.cityguide.user.*;import java.security.SecureRandom;import java.util.*;import org.springframework.boot.CommandLineRunner;import org.springframework.context.annotation.Profile;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.stereotype.Component;import org.springframework.transaction.annotation.Transactional;
@Component @Profile("local")
public class DevDataInitializer implements CommandLineRunner {
 private static final String[] NAMES={"Amara O.","Liam K.","Sofia R.","Kenji T.","Priya S.","Daniel M.","Chloé B."};private static final String[] EMAILS={"amara@seed.cityguide.app","liam@seed.cityguide.app","sofia@seed.cityguide.app","kenji@seed.cityguide.app","priya@seed.cityguide.app","daniel@seed.cityguide.app","chloe@seed.cityguide.app"};private static final String[] TEXTS={"Absolutely worth it. Go early to avoid the crowds.","Great atmosphere and friendly staff. Would visit again.","A highlight of our trip – the photos don’t do it justice.","Well organised and easy to reach by public transport.","Lovely spot. A little busy at weekends but still enjoyable.","Good value and a memorable experience overall.","Exactly what I hoped for. Highly recommended for first-timers."};
 private final UserRepository users;private final PlaceRepository places;private final ReviewRepository reviews;private final ReviewLikeRepository likes;private final FavoriteRepository favorites;private final PasswordEncoder encoder;private final SecureRandom random=new SecureRandom();
 public DevDataInitializer(UserRepository u,PlaceRepository p,ReviewRepository r,ReviewLikeRepository l,FavoriteRepository f,PasswordEncoder e){users=u;places=p;reviews=r;likes=l;favorites=f;encoder=e;}
 @Override @Transactional public void run(String... args){User demo=users.findByEmailIgnoreCase("demo@cityguide.app").orElseGet(()->{User u=new User();u.setName("Demo Traveller");u.setEmail("demo@cityguide.app");u.setPhone("+1 555 0100");u.setPasswordHash(encoder.encode("Demo@1234"));return users.save(u);});addFavorite(demo.getId(),"eiffel");addFavorite(demo.getId(),"centralpark");List<User> reviewers=new ArrayList<>();for(int i=0;i<EMAILS.length;i++){final int index=i;User u=users.findByEmailIgnoreCase(EMAILS[i]).orElseGet(()->{byte[] b=new byte[32];random.nextBytes(b);User x=new User();x.setName(NAMES[index]);x.setEmail(EMAILS[index]);x.setPasswordHash(encoder.encode(Base64.getUrlEncoder().withoutPadding().encodeToString(b)));return users.save(x);});reviewers.add(u);}
 for(Place p:places.findAll()){int start=Math.floorMod(p.getId().hashCode(),reviewers.size());int[] ratings={(int)Math.round(p.getBaseRating()),(int)Math.ceil(p.getBaseRating()),(int)Math.floor(p.getBaseRating())};for(int j=0;j<3;j++){int index=(start+j)%reviewers.size();User author=reviewers.get(index);if(reviews.findByPlaceIdAndUserId(p.getId(),author.getId()).isEmpty()){Review r=new Review();r.setPlaceId(p.getId());r.setUserId(author.getId());r.setRating((short)Math.max(1,Math.min(5,ratings[j])));r.setText(TEXTS[index]);reviews.save(r);}}}
 for(Review r:reviews.findAll()){int authorIndex=-1;for(int i=0;i<reviewers.size();i++)if(reviewers.get(i).getId().equals(r.getUserId()))authorIndex=i;int added=0;for(int i=0;i<reviewers.size()&&added<2;i++){if(i==authorIndex)continue;ReviewLike.Key key=new ReviewLike.Key(r.getId(),reviewers.get(i).getId());if(!likes.existsById(key)){ReviewLike like=new ReviewLike();like.setReviewId(r.getId());like.setUserId(reviewers.get(i).getId());likes.save(like);added++;}}}
 for(Place p:places.findAll()){List<Review> rows=reviews.findByPlaceIdOrderByCreatedAtDesc(p.getId());p.setReviewCount(rows.size());p.setRatingAvg(rows.isEmpty()?p.getBaseRating():rows.stream().mapToInt(Review::getRating).average().orElse(p.getBaseRating()));}}
 private void addFavorite(UUID user,String place){if(places.existsById(place)){Favorite.Key key=new Favorite.Key(user,place);if(!favorites.existsById(key)){Favorite f=new Favorite();f.setUserId(user);f.setPlaceId(place);favorites.save(f);}}}
}
